CREATE TABLE IF NOT EXISTS InventorySale (id VARCHAR(191) NOT NULL, billNumber VARCHAR(30) NOT NULL, requestHash VARCHAR(64) NOT NULL, snapshot JSON NOT NULL, total DECIMAL(14,2) NOT NULL, paid DECIMAL(14,2) NOT NULL, method VARCHAR(30) NULL, reference VARCHAR(191) NULL, createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY(id), UNIQUE INDEX InventorySale_billNumber_key(billNumber)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;